def convertir_estados(apps, schema_editor):
    """pendiente/proceso -> según anticipo (sin anticipo / poco anticipo / hacer)."""
    from decimal import Decimal

    Pedido = apps.get_model("ventas", "Pedido")
    Pago = apps.get_model("ventas", "Pago")
    for pedido in Pedido.objects.filter(estado__in=["pendiente", "proceso"]):
        pagado = sum((p.monto for p in Pago.objects.filter(pedido=pedido)), Decimal("0"))
        if pagado <= 0:
            estado = "sin_anticipo"
        elif pedido.total > 0 and pagado * 2 < pedido.total:
            estado = "poco_anticipo"
        else:
            estado = "hacer"
        Pedido.objects.filter(pk=pedido.pk).update(estado=estado)


def revertir_estados(apps, schema_editor):
    Pedido = apps.get_model("ventas", "Pedido")
    Pedido.objects.filter(estado__in=["sin_anticipo", "poco_anticipo"]).update(estado="pendiente")
    Pedido.objects.filter(estado="hacer").update(estado="proceso")
    Pedido.objects.filter(estado="devolucion").update(estado="entregado")


